#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# GitHub access for ai-tutor: organization, GitHub App (server actions,
# OAuth for learners, webhooks via smee.io), test learner accounts.
# Run from the repository root: scripts/setup-github.sh
# Variables: docs/implementation-decisions.md, «Недостающие доступы».

TOTAL_STAGES=9
APP_CALLBACK="http://localhost:8080/api/github/callback"
KEY_PATH=".secrets/github-app.pem"

# copy_to_clipboard VALUE puts a secret on the clipboard instead of the screen.
copy_to_clipboard() {
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

banner "ai-tutor: доступ к GitHub"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Организация платформы"
say "Учебные репозитории учеников живут в отдельной организации. Хватит тарифа Free."
say "Если организация уже есть, просто введите её имя."
open_url "https://github.com/account/organizations/new?plan=free"
step "Придумайте имя (например ai-tutor-practice-<ваш-ник>), укажите почту, «My personal account»."
step "Создайте организацию; приглашать участников не нужно (Skip this step)."
ask GITHUB_ORG "Имя организации (как в адресе github.com/<имя>):"
write_env GITHUB_ORG "$GITHUB_ORG"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Канал вебхуков smee.io"
say "GitHub не достучится до localhost, поэтому события идут через канал smee.io."
open_url "https://smee.io/new"
step "Страница сразу создаёт канал. Скопируйте адрес вида https://smee.io/AbCd… (Webhook Proxy URL)."
ask SMEE_URL "Адрес канала smee.io:"
write_env SMEE_URL "$SMEE_URL"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub App: создание"
GITHUB_WEBHOOK_SECRET=$(_existing GITHUB_WEBHOOK_SECRET || true)
if [[ -z "$GITHUB_WEBHOOK_SECRET" ]]; then
  GITHUB_WEBHOOK_SECRET=$(openssl rand -hex 32)
fi
write_env GITHUB_WEBHOOK_SECRET "$GITHUB_WEBHOOK_SECRET"
open_url "https://github.com/organizations/${GITHUB_ORG}/settings/apps/new"
step "GitHub App name: любое свободное имя, например ai-tutor-${GITHUB_ORG}."
step "Homepage URL: http://localhost:8080"
step "Callback URL: ${APP_CALLBACK}"
step "Webhook: Active ✓, Webhook URL: ${SMEE_URL}"
if copy_to_clipboard "$GITHUB_WEBHOOK_SECRET"; then
  step "Webhook secret: вставьте из буфера обмена (Cmd/Ctrl+V) — секрет уже скопирован."
else
  step "Webhook secret: значение GITHUB_WEBHOOK_SECRET из файла $ENV_FILE (на экран не выводим)."
fi
step "Repository permissions: Administration — Read and write; Checks — Read and write;"
step "  Contents — Read and write; Pull requests — Read and write; Metadata — Read-only."
step "Subscribe to events: Pull request."
step "Where can this GitHub App be installed: Only on this account. Нажмите Create GitHub App."
ask GITHUB_APP_ID "App ID (число вверху страницы About):"
write_env GITHUB_APP_ID "$GITHUB_APP_ID"
ask GITHUB_APP_SLUG "Короткое имя App из адреса github.com/apps/<имя> (Public link):"
write_env GITHUB_APP_SLUG "$GITHUB_APP_SLUG"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub App: OAuth для учеников"
say "Ученик подключает свой GitHub-аккаунт через OAuth этой же App."
open_url "https://github.com/organizations/${GITHUB_ORG}/settings/apps/${GITHUB_APP_SLUG}"
step "На странице General скопируйте Client ID."
ask GITHUB_APP_CLIENT_ID "Client ID:"
write_env GITHUB_APP_CLIENT_ID "$GITHUB_APP_CLIENT_ID"
step "Нажмите Generate a new client secret и скопируйте его (GitHub покажет один раз)."
ask_secret GITHUB_APP_CLIENT_SECRET "Client secret (ввод скрыт):"
write_env GITHUB_APP_CLIENT_SECRET "$GITHUB_APP_CLIENT_SECRET"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub App: приватный ключ"
say "Ключ подписывает запросы платформы. Он ляжет в ${KEY_PATH} (каталог в .gitignore)."
step "Там же, внизу страницы General: Private keys → Generate a private key. Браузер скачает .pem."
if [[ -f "$KEY_PATH" ]] && ! confirm "Ключ ${KEY_PATH} уже есть. Заменить его новым?"; then
  note "оставляю существующий ключ"
else
  pem=""
  while [[ ! -f "$pem" ]]; do
    ask pem "Путь к скачанному .pem (можно перетащить файл в терминал):"
    pem="${pem//\'/}"; pem="${pem%"${pem##*[![:space:]]}"}"
    [[ -f "$pem" ]] || warn "файл не найден: $pem"
  done
  mkdir -p "$(dirname "$KEY_PATH")"
  mv "$pem" "$KEY_PATH"
  chmod 600 "$KEY_PATH"
  printf '  %s✓ moved%s key → %s\n' "$GREEN" "$RESET" "$KEY_PATH"
fi
write_env GITHUB_APP_PRIVATE_KEY_PATH "$KEY_PATH"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Установка App в организацию"
open_url "https://github.com/apps/${GITHUB_APP_SLUG}/installations/new"
step "Выберите организацию ${GITHUB_ORG}."
step "Repository access: All repositories → Install."
pause "Установили? Нажмите Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Тестовые аккаунты учеников"
say "Для проверки «ученик Б не видит репозиторий ученика А» нужны два обычных GitHub-аккаунта,"
say "не владельцы и не участники организации ${GITHUB_ORG}."
open_url "https://github.com/signup"
step "Если аккаунтов нет, зарегистрируйте два (подойдут почтовые алиасы вида you+a@…)."
ask GITHUB_TEST_LEARNER_A "Логин GitHub ученика А:"
write_env GITHUB_TEST_LEARNER_A "$GITHUB_TEST_LEARNER_A"
ask GITHUB_TEST_LEARNER_B "Логин GitHub ученика Б:"
write_env GITHUB_TEST_LEARNER_B "$GITHUB_TEST_LEARNER_B"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Лимит расходов OpenAI"
say "Ключ OPENAI_API_KEY уже есть в ${ENV_FILE}. Убедитесь, что у проекта стоит лимит расходов."
open_url "https://platform.openai.com/settings/organization/limits"
step "Проверьте или задайте месячный бюджет проекта, которому принадлежит ключ."
if ! confirm "Лимит расходов выставлен?"; then
  SKIPPED+=("лимит расходов OpenAI: https://platform.openai.com/settings/organization/limits")
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Проверка доступа"
say "Проверяю: App принимает подпись (GET /app) и установлена в ${GITHUB_ORG} (GET /orgs/${GITHUB_ORG})."
if (set -a; . "./$ENV_FILE"; set +a; go run ./backend/cmd/ghcheck); then
  pause "Готово. Enter — итог."
else
  warn "проверка не прошла: исправьте шаг выше и запустите скрипт снова (значения сохранены)"
  SKIPPED+=("проверка доступа: go run ./backend/cmd/ghcheck с переменными из $ENV_FILE")
  pause "Enter — итог."
fi

finish
